#!/bin/bash
# Uninstall script for Sonos S2
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Sonos S2..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Sonos S2 if running..."
pkill -f "Sonos S2" 2>/dev/null || true

# Kill application with bundle ID com.sonos.macController2 if running
echo "Stopping application with bundle ID com.sonos.macController2 if running..."
killall -9 "com.sonos.macController2" 2>/dev/null || true

# Remove /Applications/Sonos.app
echo "Removing /Applications/Sonos.app..."
if [ -d "/Applications/Sonos.app" ]; then
    rm -rf "/Applications/Sonos.app" 2>/dev/null || true
elif [ -f "/Applications/Sonos.app" ]; then
    rm -f "/Applications/Sonos.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/CrashReporter/Sonos_*.plist
echo "Removing $HOME/Library/Application Support/CrashReporter/Sonos_*.plist..."
