    rm -rf "$HOME/Library/Application Support/CrashReporter/Sonos_*.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/CrashReporter/Sonos_*.plist" ]; then
    rm -f "$HOME/Library/Application Support/CrashReporter/Sonos_*.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/SonosV2
