elif [ -f "$HOME/Library/Caches/com.sonos.macController2" ]; then
    rm -f "$HOME/Library/Caches/com.sonos.macController2" 2>/dev/null || true
fi

# Remove $HOME/Library/HTTPStorages/com.sonos.macController2
echo "Removing $HOME/Library/HTTPStorages/com.sonos.macController2..."
if [ -d "$HOME/Library/HTTPStorages/com.sonos.macController2" ]; then
