# Remove $HOME/Library/Preferences/com.sonos.macController2.plist
echo "Removing $HOME/Library/Preferences/com.sonos.macController2.plist..."
if [ -d "$HOME/Library/Preferences/com.sonos.macController2.plist" ]; then
